import { loadFont } from "@remotion/google-fonts/Inter";
import { parse, type Font } from "opentype.js";
import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, continueRender, delayRender, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The guide lines drawing in, then each letter in turn: its outline and
// anchors popping in along the path, its handles pulled out to their place,
// the fill coming in and the scaffolding fading. Frames on the 30 fps scene
// timeline, after `speed`. The ids are public: a saved `timing` prop refers
// to them.

type GlyphAnatomyElementId = `guide:${number}` | `letter:${number}`;

interface GlyphAnatomyTimingProps {
  text?: string;
  guides?: boolean;
}

/** Beats on the 30 fps clock. Letter beats shift by `letterStagger × i`. */
const anatomyTiming = {
  guideStart: 0,
  guideStagger: 3,
  guideDraw: 10,
  anchors: [8, 22],
  anchorPop: 4,
  /** Frames the outline takes to fade in, from the first anchor. */
  outline: 4,
  pull: [18, 40],
  pullDuration: 8,
  fill: [40, 50],
  fade: [46, 58],
  letterStagger: 2,
} as const;

/** A letter's moments, in frames from its own start. */
interface LetterSpans {
  anchors: readonly [number, number];
  anchorPop: number;
  outline: number;
  pull: readonly [number, number];
  pullDuration: number;
  fill: readonly [number, number];
  fade: readonly [number, number];
}

const GUIDE_LABELS = ["Cap height", "x-height", "Baseline", "Descender"];

// `guide:<i>` draws guide line `i`, a chain. `letter:<i>` is letter `i`,
// from its first anchor's wait to its scaffolding gone; the letters form a
// chain. A letter's beats are its moments from its start: anchors pop from
// `anchors` to `anchorsEnd`, each over `anchorPop`, the outline fades in over
// `outline`, handles are pulled from `pull` to `pullEnd`, each over
// `pullDuration`, the fill runs from `fill` to `fillEnd`, and the scaffolding
// fades from `fade` to the letter's end. How many anchors and handles share
// those spans comes from the font.
const glyphAnatomyTimeline = defineTimeline<
  GlyphAnatomyElementId,
  GlyphAnatomyTimingProps
>(({ text = "Glyph", guides = true }) => {
  const T = anatomyTiming;
  const elements: TimelineElement<GlyphAnatomyElementId>[] = [];
  if (guides) {
    GUIDE_LABELS.forEach((label, i) => {
      elements.push({
        id: `guide:${i}`,
        lane: "Guides",
        label,
        start: T.guideStart + T.guideStagger * i,
        length: T.guideDraw,
        follows: i > 0 ? `guide:${i - 1}` : undefined,
      });
    });
  }
  Array.from(text).forEach((char, i) => {
    elements.push({
      id: `letter:${i}`,
      lane: "Letters",
      label: char,
      start: T.letterStagger * i,
      length: T.fade[1],
      follows: i > 0 ? `letter:${i - 1}` : undefined,
      beats: {
        anchors: T.anchors[0],
        anchorsEnd: T.anchors[1],
        anchorPop: T.anchorPop,
        outline: T.outline,
        pull: T.pull[0],
        pullEnd: T.pull[1],
        pullDuration: T.pullDuration,
        fill: T.fill[0],
        fillEnd: T.fill[1],
        fade: T.fade[0],
      },
    });
  });
  return elements.sort((a, b) => a.start - b.start);
});

const { fontFamily: INTER } = loadFont("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

interface GlyphAnatomyProps {
  text?: string;
  fontUrl?: string;
  fontSize?: number;
  color?: string;
  guideColor?: string;
  guides?: boolean;
  keepPoints?: boolean;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches single guides and letters, by the ids in
   * `./timeline`. Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<GlyphAnatomyElementId>;
}

/** Static Inter ExtraBold (800) from Google Fonts. */
const interExtraBoldTtf =
  "https://fonts.gstatic.com/s/inter/v20/UcCO3FwrK3iLTeHuS_nVMrMxCp50SjIw2boKoduKmMEVuDyYMZg.ttf";

const glyphAnatomyDefaults = {
  text: "Glyph",
  fontUrl: interExtraBoldTtf,
  fontSize: 200,
  color: "#fafafa",
  guideColor: "#0d99ff",
  guides: true,
  keepPoints: false,
  speed: 1,
} satisfies Required<Omit<GlyphAnatomyProps, "className" | "timing">>;

/** Beats on the 30 fps clock. Letter beats shift by `letterStagger × i`. */
const glyphAnatomyTiming = anatomyTiming;

/** A letter's moments, read from its element in the schedule. */
function letterSpans(e: ResolvedElement<GlyphAnatomyElementId>): LetterSpans {
  return {
    anchors: [e.beat("anchors"), e.beat("anchorsEnd")],
    anchorPop: e.beat("anchorPop"),
    outline: e.beat("outline"),
    pull: [e.beat("pull"), e.beat("pullEnd")],
    pullDuration: e.beat("pullDuration"),
    fill: [e.beat("fill"), e.beat("fillEnd")],
    fade: [e.beat("fade"), e.length],
  };
}

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const easeOutCubic = Easing.out(Easing.cubic);
const easeInOutCubic = Easing.inOut(Easing.cubic);
const popEase = Easing.out(Easing.back(1.7));
const pullEase = Easing.out(Easing.back(1.6));

function finite(value: number | undefined, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

/** Maps a composition frame onto the 30 fps timeline, scaled by `speed`. */
function getGlyphAnatomyTime(
  frame: number,
  options: { fps?: number; speed?: number } = {},
) {
  const fps = Math.max(1, finite(options.fps, 30));
  const speed = Math.max(0, finite(options.speed, 1));
  return (Math.max(0, finite(frame, 0)) * 30 * speed) / fps;
}

interface Point {
  x: number;
  y: number;
}

interface AnatomySegment {
  from: Point;
  to: Point;
  /** Cubic handles; absent on straight segments. */
  c1?: Point;
  c2?: Point;
}

interface PathCommand {
  type: string;
  x?: number;
  y?: number;
  x1?: number;
  y1?: number;
  x2?: number;
  y2?: number;
}

const lerp = (a: Point, b: Point, k: number): Point => ({
  x: a.x + (b.x - a.x) * k,
  y: a.y + (b.y - a.y) * k,
});

/**
 * Turns glyph path commands into contours of explicit segments. Quadratic
 * curves become cubics (handles at ⅔ toward the control point), so every
 * curve shows one handle on each end, as in Figma or Glyphs.
 */
function getAnatomyContours(
  commands: readonly PathCommand[],
): AnatomySegment[][] {
  const contours: AnatomySegment[][] = [];
  let segments: AnatomySegment[] = [];
  let start: Point | null = null;
  let at: Point | null = null;
  const close = () => {
    if (start && at && (at.x !== start.x || at.y !== start.y)) {
      segments.push({ from: at, to: start });
    }
    if (segments.length > 0) contours.push(segments);
    segments = [];
    start = null;
    at = null;
  };
  for (const c of commands) {
    const to = { x: c.x ?? 0, y: c.y ?? 0 };
    if (c.type === "M") {
      close();
      start = to;
      at = to;
    } else if (!at) {
    } else if (c.type === "L") {
      segments.push({ from: at, to });
      at = to;
    } else if (c.type === "Q") {
      const q = { x: c.x1 ?? 0, y: c.y1 ?? 0 };
      segments.push({
        from: at,
        to,
        c1: lerp(at, q, 2 / 3),
        c2: lerp(to, q, 2 / 3),
      });
      at = to;
    } else if (c.type === "C") {
      segments.push({
        from: at,
        to,
        c1: { x: c.x1 ?? 0, y: c.y1 ?? 0 },
        c2: { x: c.x2 ?? 0, y: c.y2 ?? 0 },
      });
      at = to;
    } else if (c.type === "Z") {
      close();
    }
  }
  close();
  return contours;
}

/**
 * How far each handle has travelled from its anchor to its place, 0 → 1 with
 * overshoot. At 0 the curve is its chord.
 */
function getGlyphAnatomyPull(
  t: number,
  order: number,
  total: number,
  spans: Pick<LetterSpans, "pull" | "pullDuration"> = glyphAnatomyTiming,
) {
  const { pull, pullDuration } = spans;
  const span = pull[1] - pull[0] - pullDuration;
  const start = pull[0] + (total > 1 ? (span * order) / (total - 1) : 0);
  return interpolate(t, [start, start + pullDuration], [0, 1], {
    ...CLAMP,
    easing: pullEase,
  });
}

/** Scale of anchor `order` of `total` popping in along the letter's path. */
function getGlyphAnatomyAnchor(
  t: number,
  order: number,
  total: number,
  spans: Pick<LetterSpans, "anchors" | "anchorPop"> = glyphAnatomyTiming,
) {
  const { anchors, anchorPop } = spans;
  const span = anchors[1] - anchors[0] - anchorPop;
  const start = anchors[0] + (total > 1 ? (span * order) / (total - 1) : 0);
  return Math.max(
    0,
    interpolate(t, [start, start + anchorPop], [0, 1], {
      ...CLAMP,
      easing: popEase,
    }),
  );
}

/** Letter-level fades: outline in, fill in, scaffolding out. */
function getGlyphAnatomyLetter(
  t: number,
  spans: Pick<
    LetterSpans,
    "anchors" | "outline" | "fill" | "fade"
  > = glyphAnatomyTiming,
) {
  const { anchors, outline, fill, fade } = spans;
  return {
    outline: interpolate(t, [anchors[0], anchors[0] + outline], [0, 1], CLAMP),
    fill: interpolate(t, [...fill], [0, 1], {
      ...CLAMP,
      easing: easeInOutCubic,
    }),
    scaffold: interpolate(t, [...fade], [1, 0], {
      ...CLAMP,
      easing: easeInOutCubic,
    }),
  };
}

/** Draw progress of guide `index`, 0..1; `span` is its element. */
function getGlyphAnatomyGuide(
  t: number,
  index: number,
  span?: { start: number; end: number },
) {
  const { guideStart, guideStagger, guideDraw } = glyphAnatomyTiming;
  const start = span ? span.start : guideStart + guideStagger * index;
  const end = span ? span.end : start + guideDraw;
  return interpolate(t, [start, end], [0, 1], {
    ...CLAMP,
    easing: easeOutCubic,
  });
}

/** Frame where the scaffolding of the last of `count` letters has faded. */
function getGlyphAnatomyLength(count: number) {
  const { fade, letterStagger } = glyphAnatomyTiming;
  return fade[1] + letterStagger * Math.max(0, count - 1);
}

/** Path data for a contour with each handle pulled `k(segment)` of the way. */
function getAnatomyPath(
  segments: readonly AnatomySegment[],
  pullOf: (index: number) => number,
) {
  if (segments.length === 0) return "";
  const f = (p: Point) => `${p.x.toFixed(2)} ${p.y.toFixed(2)}`;
  let d = `M${f(segments[0].from)}`;
  segments.forEach((s, i) => {
    if (s.c1 && s.c2) {
      const k = pullOf(i);
      d += `C${f(lerp(s.from, s.c1, k))} ${f(lerp(s.to, s.c2, k))} ${f(s.to)}`;
    } else {
      d += `L${f(s.to)}`;
    }
  });
  return `${d}Z`;
}

interface AnatomyLetter {
  contours: AnatomySegment[][];
}

function layout(font: Font, text: string, fontSize: number) {
  const scale = fontSize / font.unitsPerEm;
  // Per-character lookup: full shaping runs GSUB lookups that opentype.js
  // does not support in every font.
  const glyphs = Array.from(text).map((char) => font.charToGlyph(char));
  let x = 0;
  const letters: AnatomyLetter[] = glyphs.map((glyph, i) => {
    if (i > 0) x += font.getKerningValue(glyphs[i - 1], glyph) * scale;
    const contours = getAnatomyContours(glyph.getPath(x, 0, fontSize).commands);
    x += (glyph.advanceWidth ?? 0) * scale;
    return { contours };
  });
  const os2 = font.tables.os2 as
    | { sCapHeight?: number; sxHeight?: number }
    | undefined;
  const em = (v: number | undefined, fallback: number) =>
    ((v ?? fallback * font.unitsPerEm) * fontSize) / font.unitsPerEm;
  return {
    letters,
    width: x,
    capHeight: em(os2?.sCapHeight, 0.7),
    xHeight: em(os2?.sxHeight, 0.5),
    descender: (-font.descender * fontSize) / font.unitsPerEm,
  };
}

const fontCache = new Map<string, Promise<Font>>();

function loadAnatomyFont(url: string) {
  let pending = fontCache.get(url);
  if (!pending) {
    pending = fetch(url)
      .then((res) => res.arrayBuffer())
      .then((buffer) => parse(buffer));
    fontCache.set(url, pending);
    pending.catch(() => fontCache.delete(url));
  }
  return pending;
}

function useAnatomyFont(url: string) {
  const [font, setFont] = useState<Font | null>(null);

  useEffect(() => {
    const handle = delayRender(`glyph-anatomy: loading ${url}`);
    let released = false;
    const release = () => {
      if (released) return;
      released = true;
      continueRender(handle);
    };
    loadAnatomyFont(url).then((parsed) => {
      if (!released) setFont(parsed);
      release();
    }, release);
    return release;
  }, [url]);

  return font;
}

function GlyphAnatomyBase(props: GlyphAnatomyProps) {
  const {
    text = glyphAnatomyDefaults.text,
    fontUrl = glyphAnatomyDefaults.fontUrl,
    fontSize = glyphAnatomyDefaults.fontSize,
    color = glyphAnatomyDefaults.color,
    guideColor = glyphAnatomyDefaults.guideColor,
    guides = glyphAnatomyDefaults.guides,
    keepPoints = glyphAnatomyDefaults.keepPoints,
    speed = glyphAnatomyDefaults.speed,
    className,
    timing,
  } = props;
  const frame = useSceneFrame();
  const { fps, width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    glyphAnatomyTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const font = useAnatomyFont(fontUrl);
  if (!font) return null;

  const unit = height / 720;
  const t = getGlyphAnatomyTime(frame, { fps, speed });
  const word = layout(font, text, fontSize);
  const originX = (width - word.width * unit) / 2;
  const baseline = (height + word.capHeight * unit) / 2;
  const hair = 1.25;
  const anchorSize = 6;
  const handleRadius = 2.6;
  const margin = 0.3 * fontSize;
  const letterEls = word.letters.map((_, i) => tl.get(`letter:${i}`));
  // Guides fade with the last letter's scaffolding.
  const lastEl = letterEls[letterEls.length - 1];
  const scaffoldAll = keepPoints
    ? 1
    : lastEl
      ? getGlyphAnatomyLetter(t - lastEl.start, letterSpans(lastEl)).scaffold
      : getGlyphAnatomyLetter(t).scaffold;

  const guideYs = [-word.capHeight, -word.xHeight, 0, word.descender];
  const guideLines = GUIDE_LABELS.map((label, i) => ({ label, y: guideYs[i] }));

  return (
    <div
      className={className}
      style={{ position: "absolute", inset: 0, overflow: "hidden" }}
    >
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        style={{ display: "block" }}
      >
        <g transform={`translate(${originX} ${baseline}) scale(${unit})`}>
          {guides
            ? guideLines.map((guide, i) => {
                const draw = getGlyphAnatomyGuide(t, i, tl.get(`guide:${i}`));
                if (draw <= 0) return null;
                const length = word.width + 2 * margin;
                return (
                  <g key={guide.label} opacity={0.7 * scaffoldAll}>
                    <line
                      x1={-margin}
                      x2={-margin + length * draw}
                      y1={guide.y}
                      y2={guide.y}
                      stroke={guideColor}
                      strokeWidth={hair * 0.8}
                    />
                    <text
                      x={-margin}
                      y={guide.y - 5}
                      fill={guideColor}
                      fontFamily={INTER}
                      fontSize={11}
                      fontWeight={500}
                      opacity={draw}
                    >
                      {guide.label}
                    </text>
                  </g>
                );
              })
            : null}
          {word.letters.map((letter, i) => {
            const letterEl = letterEls[i];
            const spans = letterSpans(letterEl);
            const lt = t - letterEl.start;
            const state = getGlyphAnatomyLetter(lt, spans);
            const scaffold = keepPoints ? 1 : state.scaffold;
            const curves = letter.contours.flatMap((segments, c) =>
              segments.flatMap((s, k) => (s.c1 ? [`${c}:${k}`] : [])),
            );
            const curveOrder = new Map(curves.map((key, n) => [key, n]));
            const anchors = letter.contours.flatMap((segments) =>
              segments.map((s) => s.from),
            );
            const pullOf = (c: number) => (k: number) =>
              getGlyphAnatomyPull(
                lt,
                curveOrder.get(`${c}:${k}`) ?? 0,
                curves.length,
                spans,
              );
            const paths = letter.contours.map((segments, c) =>
              getAnatomyPath(segments, pullOf(c)),
            );
            let anchorIndex = 0;
            return (
              <g key={i}>
                {state.fill > 0 ? (
                  <path d={paths.join("")} fill={color} opacity={state.fill} />
                ) : null}
                {state.outline > 0 && scaffold > 0 ? (
                  <g opacity={scaffold}>
                    {paths.map((d, c) => (
                      <path
                        key={c}
                        d={d}
                        fill="none"
                        stroke={color}
                        strokeWidth={hair}
                        opacity={state.outline}
                      />
                    ))}
                    {letter.contours.map((segments, c) =>
                      segments.map((s, k) => {
                        if (!s.c1 || !s.c2) return null;
                        const pull = pullOf(c)(k);
                        if (pull <= 0) return null;
                        const h1 = lerp(s.from, s.c1, pull);
                        const h2 = lerp(s.to, s.c2, pull);
                        return (
                          <g key={`${c}-${k}`}>
                            <line
                              x1={s.from.x}
                              y1={s.from.y}
                              x2={h1.x}
                              y2={h1.y}
                              stroke={guideColor}
                              strokeWidth={hair * 0.8}
                            />
                            <line
                              x1={s.to.x}
                              y1={s.to.y}
                              x2={h2.x}
                              y2={h2.y}
                              stroke={guideColor}
                              strokeWidth={hair * 0.8}
                            />
                            <circle
                              cx={h1.x}
                              cy={h1.y}
                              r={handleRadius}
                              fill={guideColor}
                            />
                            <circle
                              cx={h2.x}
                              cy={h2.y}
                              r={handleRadius}
                              fill={guideColor}
                            />
                          </g>
                        );
                      }),
                    )}
                    {letter.contours.map((segments, c) =>
                      segments.map((s, k) => {
                        const scale = getGlyphAnatomyAnchor(
                          lt,
                          anchorIndex++,
                          anchors.length,
                          spans,
                        );
                        if (scale <= 0) return null;
                        const size = anchorSize * scale;
                        return (
                          <rect
                            key={`${c}-${k}`}
                            x={s.from.x - size / 2}
                            y={s.from.y - size / 2}
                            width={size}
                            height={size}
                            fill="#ffffff"
                            stroke={guideColor}
                            strokeWidth={hair}
                          />
                        );
                      }),
                    )}
                  </g>
                ) : null}
              </g>
            );
          })}
        </g>
      </svg>
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  text: {
    type: "text-content",
    default: "Glyph",
    description: "Text",
  },
  color: {
    type: "color",
    default: "#fafafa",
    description: "Glyph color",
  },
  guideColor: {
    type: "color",
    default: "#0d99ff",
    description: "Points",
  },
  fontSize: {
    type: "number",
    default: 200,
    min: 80,
    max: 320,
    step: 2,
    description: "Font size",
    hiddenFromList: false,
  },
  guides: {
    type: "boolean",
    default: true,
    description: "Guides",
  },
  keepPoints: {
    type: "boolean",
    default: false,
    description: "Keep points",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["text","color","guideColor","fontSize","guides","keepPoints","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  text: "Glyph",
  color: "#fafafa",
  guideColor: "#0d99ff",
  fontSize: 200,
  guides: true,
  keepPoints: false,
  speed: 1,
};

type GlyphAnatomyElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof GlyphAnatomyBase>;

const GlyphAnatomyInner = forwardRef<
  HTMLDivElement,
  GlyphAnatomyElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<GlyphAnatomy>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <GlyphAnatomyBase
          {...(componentProps as unknown as ComponentProps<typeof GlyphAnatomyBase>)}
        />
      </div>
    </Sequence>
  );
});

export const GlyphAnatomy = Interactive.withSchema({
  Component: GlyphAnatomyInner,
  componentName: "<GlyphAnatomy>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
